INSERT INTO feature VALUES('engine-hub','editor','One engine hub per workspace and build','language-server','implemented','notable',NULL,'Every editor and tool of a workspace running one build shares one hub that holds each client''s copy of a document and judges it incrementally; the hub''s socket is named by the build and the workspace, so a client of a rebuilt driver starts a hub of its own and never reaches the old build''s, which lingers out; sibling readings, import-closure lowerings and readmissions are keyed by content and shared across connections, and a judged closure''s arena is shared with each revision laid after it, which copies only its own nodes.','surface-lsp','crates/surface-lsp/src/hub.rs crates/surface-dispatcher/src/component.rs crates/surface-driver/tests/cli.rs',NULL,'#122');
